// The rightkit-android Gradle library module.
//
// Inputs (all git-ignored build output, produced by ../scripts/build-android.*):
//   src/main/jniLibs/<abi>/librightkit_android.so   (and any app .so the build script copies there)
//   src/main/uniffi-generated/**                    (Kotlin generated by uniffi-bindgen)
//
// minSdk / ABIs / NDK are mirrored in src/abi.rs and scripts/toolchain.versions; the crate's unit
// tests fail when they drift. minSdk 28 is a choice, not in the plan: confirm.

plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
}

android {
    namespace = "com.orthiclabs.rightkit.android"
    compileSdk = 35
    ndkVersion = "27.2.12479018"

    defaultConfig {
        minSdk = 28
        consumerProguardFiles("consumer-rules.pro")
        ndk {
            abiFilters += listOf("arm64-v8a", "x86_64")
        }
    }

    sourceSets {
        getByName("main") {
            jniLibs.srcDir("src/main/jniLibs")
            // Generated UniFFI Kotlin (package com.orthiclabs.rightkit.android.core).
            java.srcDir("src/main/uniffi-generated")
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    publishing {
        singleVariant("release") { withSourcesJar() }
    }
}

kotlin {
    jvmToolchain(17)
}

dependencies {
    // UniFFI's generated Kotlin loads the library through JNA.
    api("net.java.dev.jna:jna:5.14.0@aar")
}

// Fail early with a useful message instead of an app that crashes on System.loadLibrary.
// Skip with -Prightkit.skipNativeCheck=true (for example for a Kotlin-only unit-test run).
val verifyNativeLibs by tasks.registering {
    val libs = layout.projectDirectory.dir("src/main/jniLibs")
    val abis = listOf("arm64-v8a", "x86_64")
    val skip = providers.gradleProperty("rightkit.skipNativeCheck").orNull == "true"
    doLast {
        if (skip) return@doLast
        val missing = abis.filter { !libs.file("$it/librightkit_android.so").asFile.exists() }
        check(missing.isEmpty()) {
            "Native libraries missing for ${missing.joinToString()}: run crates/rightkit-android/scripts/build-android.(sh|ps1) first."
        }
    }
}

tasks.matching { it.name == "preBuild" }.configureEach {
    dependsOn(verifyNativeLibs)
}
